/**
 * PDF.js bridge definition
 */
if (typeof window !== 'undefined' && !window.pdfjsLib) {
    window.pdfjsLib = {
        GlobalWorkerOptions: {
            workerSrc: 'pdf.worker.min.js'
        },
        Util: {
            transform: function(m1, m2) {
                return [
                    m1[0] * m2[0] + m1[2] * m2[1],
                    m1[1] * m2[0] + m1[3] * m2[1],
                    m1[0] * m2[2] + m1[2] * m2[3],
                    m1[1] * m2[2] + m1[3] * m2[3],
                    m1[0] * m2[4] + m1[2] * m2[5] + m1[4],
                    m1[1] * m2[4] + m1[3] * m2[5] + m1[5]
                ];
            }
        },
        getDocument: function(src) {
            // If loaded through CDN or overridden, this handles fallback
            return {
                promise: new Promise(function(resolve, reject) {
                    if (window._cdnPdfjsLib) {
                        return window._cdnPdfjsLib.getDocument(src).promise.then(resolve).catch(reject);
                    }
                    // Inform interface to fetch from CDN or standard viewer
                    const script = document.createElement('script');
                    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
                    script.onload = function() {
                        if (window.pdfjsLib && window.pdfjsLib !== this) {
                            window.pdfjsLib.getDocument(src).promise.then(resolve).catch(reject);
                        } else {
                            reject(new Error("PDF engine initializing"));
                        }
                    };
                    script.onerror = function() {
                        reject(new Error("Could not load PDF rendering engine offline. Please ensure network access for first launch or place full pdf.min.js in assets."));
                    };
                    document.head.appendChild(script);
                })
            };
        }
    };
}
